// Step 1 of 7 — reject an incomplete brief before anything is written anywhere.
// Mirrors intakeSchema in src/lib/model.ts. Keep the two in step.
const body = $json.body ?? $json;
const problems = [];

const text = (value) => (typeof value === 'string' ? value.trim() : '');
const contactName = text(body.contactName);
const company = text(body.company);
const email = text(body.email).toLowerCase();
const phone = text(body.phone);
const brief = text(body.brief);
const projectType = text(body.projectType);
const deadline = text(body.deadline);
const budgetGbp = Number(body.budgetGbp);

const PROJECT_TYPES = ['Brand film', 'Social campaign', 'Photography', 'Website', 'Event coverage', 'Retainer'];

if (contactName.length < 2) problems.push('contactName: give us a name we can use');
if (company.length < 2) problems.push('company: which company is this for?');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) problems.push('email: that email address does not look right');
if (phone && !/^(?:\+44\s?|0)(?:\d\s?-?){9,10}$/.test(phone)) problems.push('phone: use a UK number');
if (!PROJECT_TYPES.includes(projectType)) problems.push('projectType: not one of the options');
if (!Number.isInteger(budgetGbp) || budgetGbp < 500 || budgetGbp > 500000) problems.push('budgetGbp: between 500 and 500000');
if (!/^\d{4}-\d{2}-\d{2}$/.test(deadline) || Number.isNaN(Date.parse(deadline))) problems.push('deadline: use a real date');
if (brief.length < 20) problems.push('brief: at least a sentence or two');

return {
  json: {
    ...$json,
    valid: problems.length === 0,
    problems,
    intake: { contactName, company, email, phone, projectType, budgetGbp, deadline, brief, heardAbout: text(body.heardAbout) },
  },
};

// Step 2 of 7 — next ID in sequence, plus the fields the tracker needs.
// The sequence comes from the highest ID present, not the row count: a manually
// deleted row must not cause the next client to reuse an ID that is on an invoice.
const cfg = $('Settings').first().json.cfg;
const intake = $('Validate the submission').first().json.intake;
const rows = $input.all().map((item) => item.json).filter((row) => row['Client ID']);

let highest = 0;
for (const row of rows) {
  const match = String(row['Client ID']).match(/(\d+)$/);
  if (match) highest = Math.max(highest, Number(match[1]));
}

const clientId = 'AMRL-' + String(highest + 1).padStart(4, '0');
const now = new Date();
const submittedAt = now.toISOString();
const depositDue = new Date(now.getTime() + 7 * 86400000).toISOString().slice(0, 10);

// Round-robin by project type, so a brief always has a name on it.
const roster = String(cfg.roster || '').split(',').map((s) => s.trim()).filter(Boolean);
let hash = 0;
for (const ch of intake.projectType) hash = (hash * 31 + ch.charCodeAt(0)) | 0;
const owner = roster.length ? roster[Math.abs(hash) % roster.length] : 'Unassigned';

const folderName = (clientId + ' ' + intake.company).replace(/[\\/:*?"<>|]/g, '-').slice(0, 120);

return [{
  json: {
    cfg,
    clientId,
    folderName,
    depositAmountGbp: Math.round(intake.budgetGbp * 0.5),
    row: {
      'Client ID': clientId,
      Submitted: submittedAt,
      Contact: intake.contactName,
      Company: intake.company,
      Email: intake.email,
      Phone: intake.phone,
      'Project type': intake.projectType,
      'Budget (GBP)': intake.budgetGbp,
      Deadline: intake.deadline,
      Brief: intake.brief,
      'Heard about us': intake.heardAbout,
      'Drive folder': '',
      Status: 'New enquiry',
      Payment: 'Awaiting deposit',
      'Deposit due': depositDue,
      'Paid (GBP)': 0,
      Delivery: 'Not started',
      Delivered: '',
      Owner: owner,
      'Last updated': submittedAt,
      Notes: '',
    },
  },
}];

// One item per subfolder. The next node runs once per item, so adding a name here
// is the whole of 'add another subfolder' — no extra nodes to wire up.
const parentId = $json.id;
return [
  '01 Brief and contract',
  '02 Assets from client',
  '03 Work in progress',
  '04 Final delivery',
].map((name) => ({ json: { name, parentId } }));

